// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Delete a Fleet CRD
	// (DELETE /fleet)
	DeleteFleet(ctx context.Context, request DeleteFleetRequestObject) (DeleteFleetResponseObject, error)
	// Create a Fleet CRD
	// (POST /fleet)
	CreateFleet(ctx context.Context, request CreateFleetRequestObject) (CreateFleetResponseObject, error)
	// Update replica count on an existing Fleet
	// (PATCH /fleet/replicas)
	PatchFleetReplicas(ctx context.Context, request PatchFleetReplicasRequestObject) (PatchFleetReplicasResponseObject, error)
	// Delete a GameType CRD
	// (DELETE /game)
	DeleteGame(ctx context.Context, request DeleteGameRequestObject) (DeleteGameResponseObject, error)
	// Create a GameType CRD
	// (POST /game)
	CreateGame(ctx context.Context, request CreateGameRequestObject) (CreateGameResponseObject, error)
	// Update replica count on an existing GameType
	// (PATCH /game/replicas)
	PatchGameReplicas(ctx context.Context, request PatchGameReplicasRequestObject) (PatchGameReplicasResponseObject, error)
	// Health check
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// Delete a GameAutoscaler CRD
	// (DELETE /scaler)
	DeleteScaler(ctx context.Context, request DeleteScalerRequestObject) (DeleteScalerResponseObject, error)
	// Create a GameAutoscaler CRD
	// (POST /scaler)
	CreateScaler(ctx context.Context, request CreateScalerRequestObject) (CreateScalerResponseObject, error)
	// Delete a Server CRD
	// (DELETE /server)
	DeleteServer(ctx context.Context, request DeleteServerRequestObject) (DeleteServerResponseObject, error)
	// Create a Server CRD
	// (POST /server)
	CreateServer(ctx context.Context, request CreateServerRequestObject) (CreateServerResponseObject, error)
	// Remove a label from a server pod
	// (DELETE /server/pod/labels)
	RemovePodLabel(ctx context.Context, request RemovePodLabelRequestObject) (RemovePodLabelResponseObject, error)
	// Add a label to a server pod
	// (POST /server/pod/labels)
	AddPodLabel(ctx context.Context, request AddPodLabelRequestObject) (AddPodLabelResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

